package com.boss.industry.domain; import com.boss.common.domain.TenantScopedEntity; import jakarta.persistence.*;
@Entity @Table(name="industry_profiles") public class IndustryProfile extends TenantScopedEntity { @Column(nullable=false,length=100) private String code; @Column(nullable=false,length=200) private String name; @Column(length=4000) private String configurationJson; protected IndustryProfile(){} public IndustryProfile(String c,String n,String j){code=c;name=n;configurationJson=j;} public String getCode(){return code;} public String getName(){return name;} public String getConfigurationJson(){return configurationJson;} public void setConfigurationJson(String j){configurationJson=j;} }
